    // that might prevent the next item from fitting.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size as f64 - post_res) * 1.5;
        }
    }

    // Heuristic for new bin allocation:
    // If we are early in the stream, be conservative (prefer existing bins).
    // As the stream progresses, allow for a new bin if the current fit is poor.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // We only pick this if our current fits are all very poor (high post_residual).
        score = 80.0 + (mean_residual * 0.5) - (progress * 20.0);
    } else {
        // If this is the only bin that fits, prioritize it heavily to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Non-linear coupling: penalize high mean_residual to force consolidation.
    score += (mean_residual - post_res) * progress;

