    // If post_residual is in (0, 10), it's highly likely to be dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // 3. Lookahead Synergy (next_item_size):
    // If the next item can perfectly fit into the current post_residual, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - (diff / bin_capacity as f64));
    }

    // 4. Fitting Constraint:
    // If this is the last bin that can fit the item (fitting_bins_count == 1),
    // we should prioritize using it over opening a new bin unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1000.0; 
    }

    // 5. Global Efficiency:
    // Discourage opening new bins early in the stream unless the fit is very good.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // The cost of opening a new bin increases as the stream progresses
        score += 400.0 + (progress * 300.0);
    }

    // 6. Harmonic Modulo Bias:
    // Reward bins that align with common divisors of 100 (20, 25, 50)
    let harmonic_bias = (post_residual % 25) as f64;
    score += harmonic_bias * 2.0;

    score
}
